const LEVELS = { debug: 10, info: 20, warn: 30, error: 40, fatal: 50 };

function createLogger({ minLevel }) {
  const threshold = LEVELS[minLevel];
  return {
    log(level, msg) {
      if (LEVELS[level] < threshold) return null;
      return { level, msg };
    },
  };
}

